## My answer to the user prompt

Use **MVVM with an audio-recording service**:

- The service owns `AVAudioRecorder`, the audio session, and persistent file storage.
- The view model manages permissions, recording state, and audio-level updates.
- SwiftUI displays two buttons and a centered, audio-reactive visualization.

The visualization below shows recent microphone loudness—not frequency bands. That is sufficient for an “equalizer-like” recording indicator; actual frequency analysis would require FFT.

This example targets **iOS 17+** and saves AAC recordings in the app’s Documents directory.

### 1. Add microphone privacy configuration

In your target’s Info settings, add:

```xml
<key>NSMicrophoneUsageDescription</key>
<string>Record your voice and save audio recordings.</string>
```

Without this privacy description, requesting microphone access can terminate the app.

### 2. Audio recording service

```swift
// AudioRecordingService.swift

import AVFoundation
import Foundation

enum RecordingError: LocalizedError {
    case microphoneDenied
    case couldNotStart

    var errorDescription: String? {
        switch self {
        case .microphoneDenied:
            return "Microphone access is disabled. Enable it in Settings."
        case .couldNotStart:
            return "The audio recording could not be started."
        }
    }
}

@MainActor
protocol AudioRecordingService {
    func requestPermission() async -> Bool
    func start() throws
    func currentLevel() -> Double
    func stop() -> URL?
}

@MainActor
final class AACRecordingService: AudioRecordingService {
    private let session = AVAudioSession.sharedInstance()
    private var recorder: AVAudioRecorder?

    func requestPermission() async -> Bool {
        await withCheckedContinuation { continuation in
            AVAudioApplication.requestRecordPermission { granted in
                continuation.resume(returning: granted)
            }
        }
    }

    func start() throws {
        guard recorder == nil else { return }

        let directory = try FileManager.default.url(
            for: .documentDirectory,
            in: .userDomainMask,
            appropriateFor: nil,
            create: true
        ).appendingPathComponent("Recordings", isDirectory: true)

        try FileManager.default.createDirectory(
            at: directory,
            withIntermediateDirectories: true
        )

        let url = directory.appendingPathComponent("\(UUID().uuidString).m4a")

        do {
            try session.setCategory(.record, mode: .default)
            try session.setActive(true)

            let settings: [String: Any] = [
                AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                AVSampleRateKey: 44_100.0,
                AVNumberOfChannelsKey: 1,
                AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
            ]

            let candidate = try AVAudioRecorder(url: url, settings: settings)
            candidate.isMeteringEnabled = true

            guard candidate.prepareToRecord(), candidate.record() else {
                throw RecordingError.couldNotStart
            }

            recorder = candidate
        } catch {
            try? FileManager.default.removeItem(at: url)
            try? session.setActive(
                false,
                options: .notifyOthersOnDeactivation
            )
            throw error
        }
    }

    func currentLevel() -> Double {
        guard let recorder, recorder.isRecording else { return 0 }

        recorder.updateMeters()
        let decibels = Double(recorder.averagePower(forChannel: 0))

        // A display mapping, not a physical linear-amplitude measurement.
        return min(1, max(0, (decibels + 60) / 60))
    }

    func stop() -> URL? {
        guard let recorder else { return nil }

        let url = recorder.url
        recorder.stop() // Finalizes the audio file.
        self.recorder = nil

        try? session.setActive(
            false,
            options: .notifyOthersOnDeactivation
        )

        return url
    }
}
```

### 3. View model

The protocol makes it possible to inject a mock recording service for unit tests.

```swift
// RecorderViewModel.swift

import Combine
import Foundation

@MainActor
final class RecorderViewModel: ObservableObject {
    @Published private(set) var isRecording = false
    @Published private(set) var isBusy = false
    @Published private(set) var levels = Array(repeating: 0.0, count: 15)
    @Published private(set) var savedURL: URL?
    @Published private(set) var errorMessage: String?

    private let service: any AudioRecordingService
    private var recordingTask: Task<Void, Never>?

    init(service: any AudioRecordingService) {
        self.service = service
    }

    func start() {
        guard !isBusy else { return }

        isBusy = true
        errorMessage = nil
        savedURL = nil
        levels = Array(repeating: 0, count: levels.count)

        recordingTask = Task { [weak self] in
            guard let self else { return }

            let allowed = await service.requestPermission()

            // A stop/disappear action may have occurred during the prompt.
            guard !Task.isCancelled else { return }

            guard allowed else {
                errorMessage = RecordingError.microphoneDenied.localizedDescription
                isBusy = false
                recordingTask = nil
                return
            }

            do {
                try service.start()
                isRecording = true

                while !Task.isCancelled {
                    levels.removeFirst()
                    levels.append(service.currentLevel())
                    try await Task.sleep(for: .milliseconds(70))
                }
            } catch is CancellationError {
                // stop() already performs cleanup.
            } catch {
                _ = service.stop()
                errorMessage = error.localizedDescription
                isRecording = false
                isBusy = false
                recordingTask = nil
            }
        }
    }

    func stop() {
        recordingTask?.cancel()
        recordingTask = nil

        if let url = service.stop() {
            savedURL = url
        }

        isRecording = false
        isBusy = false
        levels = Array(repeating: 0, count: levels.count)
    }
}
```

