```rust
use std::{
    path::PathBuf,
    sync::mpsc::{self, Receiver},
};

use eframe::egui;
use notify::{RecommendedWatcher, RecursiveMode, Watcher};

#[derive(Default)]
struct FolderMonitor {
    input: Option<PathBuf>,
    output: Option<PathBuf>,
    done: Option<PathBuf>,
    watcher: Option<RecommendedWatcher>,
    events: Option<Receiver<notify::Result<notify::Event>>>,
    log: Vec<String>,
}

fn folder_row(ui: &mut egui::Ui, label: &str, path: &mut Option<PathBuf>) {
    ui.horizontal(|ui| {
        if ui.button(label).clicked() {
            if let Some(selected) = rfd::FileDialog::new().pick_folder() {
                *path = Some(selected);
            }
        }

        ui.label(
            path.as_ref()
                .map(|p| p.display().to_string())
                .unwrap_or_else(|| "Not selected".to_owned()),
        );
    });
}

impl FolderMonitor {
    fn start(&mut self, ctx: &egui::Context) {
        let Some(input) = self.input.clone() else {
            self.log.push("Select an input folder first.".into());
            return;
        };

        let (tx, rx) = mpsc::channel();
        let ctx = ctx.clone();

        let result = (|| -> notify::Result<RecommendedWatcher> {
            let mut watcher = notify::recommended_watcher(
                move |event: notify::Result<notify::Event>| {
                    let _ = tx.send(event);
                    ctx.request_repaint();
                },
            )?;

            watcher.watch(&input, RecursiveMode::NonRecursive)?;
            Ok(watcher)
        })();

        match result {
            Ok(watcher) => {
                // Keep the watcher alive for as long as monitoring is enabled.
                self.watcher = Some(watcher);
                self.events = Some(rx);
                self.log.push(format!("Monitoring {}", input.display()));
            }
            Err(error) => {
                self.log.push(format!("Could not start monitoring: {error}"));
            }
        }
    }
}

impl eframe::App for FolderMonitor {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        if let Some(rx) = &self.events {
            while let Ok(result) = rx.try_recv() {
                match result {
                    Ok(event) => {
                        let paths = event
                            .paths
                            .iter()
                            .map(|p| p.display().to_string())
                            .collect::<Vec<_>>()
                            .join(", ");

                        self.log.push(format!("{:?}: {paths}", event.kind));
                    }
                    Err(error) => {
                        self.log.push(format!("Watch error: {error}"));
                    }
                }
            }
        }

        // Bound the displayed history.
        if self.log.len() > 1_000 {
            self.log.drain(..self.log.len() - 1_000);
        }

        egui::CentralPanel::default().show(ctx, |ui| {
            ui.heading("Folder Monitor");

            // Prevent the displayed input path from differing from the watched path.
            ui.add_enabled_ui(self.watcher.is_none(), |ui| {
                folder_row(ui, "Select input folder", &mut self.input);
            });
            folder_row(ui, "Select output folder", &mut self.output);
            folder_row(ui, "Select done folder", &mut self.done);

            ui.horizontal(|ui| {
                if ui
                    .add_enabled(self.watcher.is_none(), egui::Button::new("Start"))
                    .clicked()
                {
                    self.start(ctx);
                }

                if ui
                    .add_enabled(self.watcher.is_some(), egui::Button::new("Stop"))
                    .clicked()
                {
                    self.watcher = None;
                    self.events = None;
                    self.log.push("Monitoring stopped.".into());
                }
            });

            ui.separator();
            ui.label("Activity:");

            egui::ScrollArea::vertical()
                .stick_to_bottom(true)
                .show(ui, |ui| {
                    for message in &self.log {
                        ui.label(message);
                    }
                });
        });
    }
}

fn main() -> eframe::Result<()> {
    eframe::run_native(
        "Folder Monitor",
        eframe::NativeOptions::default(),
        Box::new(|_cc| Box::new(FolderMonitor::default())),
    )
}
```

Run with:

```sh
cargo run
```

