```

**2. Add this method inside `MarkdownBlock`:**

```js
highlightQuotedText() {
    const walker = document.createTreeWalker(
        this,
        NodeFilter.SHOW_TEXT,
        {
            acceptNode(node) {
                return node.parentElement.closest(
                    "pre, code, script, style, textarea, md-span"
                )
                    ? NodeFilter.FILTER_REJECT
                    : NodeFilter.FILTER_ACCEPT;
            }
        }
    );

    // Collect nodes before modifying the DOM.
    const nodes = [];
    while (walker.nextNode()) {
        nodes.push(walker.currentNode);
    }

    for (const node of nodes) {
        const text = node.data;

        // smartypants: true may turn straight quotes into curly quotes.
        const matches = [...text.matchAll(/"[^"]+"|“[^”]+”/g)];
        if (!matches.length) continue;

        const fragment = document.createDocumentFragment();
        let offset = 0;

        for (const match of matches) {
            fragment.append(
                document.createTextNode(text.slice(offset, match.index))
            );

            const span = document.createElement("span");
            span.style.color = "red";
            span.textContent = match[0];
            fragment.append(span);

            offset = match.index + match[0].length;
        }

        fragment.append(document.createTextNode(text.slice(offset)));
        node.replaceWith(fragment);
    }
}
```

For example:

```html
<md-block>
This is "red text", and this is not.
</md-block>
```

**Scope:** This small patch handles quoted words and sentences within individual text nodes. A quotation spanning Markdown formatting, such as `"hello **world**"`, needs a cross-node implementation; this patch does not highlight that entire quotation.

Also, the supplied source is missing JavaScript template-literal backticks in several places. Those must be restored for the module to run, for example:

```js
