## My answer to the user prompt

Use an **unclamped, invisible copy of the text to detect overflow**, then reserve space for a separate “See more” control on the same row.

Appending “See more” after the complete text inside a `Text` with `numberOfLines={1}` does not work reliably: React Native can truncate the link along with the content.

Here is a dependency-free implementation:

```jsx
// ExpandableText.jsx
import React, { useState } from 'react';
import {
  Pressable,
  StyleSheet,
  Text,
  View,
  useWindowDimensions,
} from 'react-native';

function MeasuredText({
  text,
  width,
  textStyle,
  linkStyle,
  seeMoreLabel,
  onExpand,
}) {
  const [overflows, setOverflows] = useState(false);
  const [expanded, setExpanded] = useState(false);

  const expand = () => {
    setExpanded(true);
    onExpand?.();
  };

  return (
    <View style={styles.content}>
      {/* Measure the complete text without numberOfLines. */}
      <View
        pointerEvents="none"
        accessible={false}
        accessibilityElementsHidden
        importantForAccessibility="no-hide-descendants"
        style={[styles.measurement, { width }]}
      >
        <Text
          style={[styles.text, textStyle]}
          onTextLayout={({ nativeEvent }) => {
            const next = nativeEvent.lines.length > 1;
            setOverflows(previous =>
              previous === next ? previous : next
            );
          }}
        >
          {text}
        </Text>
      </View>

      {expanded ? (
        <Text style={[styles.text, textStyle]}>{text}</Text>
      ) : (
        <View style={styles.row}>
          <Text
            style={[styles.text, textStyle, styles.preview]}
            numberOfLines={1}
            ellipsizeMode="tail"
          >
            {text}
          </Text>

          {overflows && (
            <Pressable
              onPress={expand}
              accessibilityRole="button"
              accessibilityLabel={seeMoreLabel}
              accessibilityHint="Shows the full text"
              accessibilityState={{ expanded: false }}
              hitSlop={8}
              style={({ pressed }) => [
                styles.button,
                pressed && styles.pressed,
              ]}
            >
              <Text
                numberOfLines={1}
                style={[styles.text, textStyle, styles.link, linkStyle]}
              >
                {seeMoreLabel}
              </Text>
            </Pressable>
          )}
        </View>
      )}
    </View>
  );
}

/**
 * textStyle and linkStyle should contain typography/color styles only.
 * Apply padding, margins, and backgrounds through style.
 *
 * The parent must provide enough width for the "See more" label.
 */
export default function ExpandableText({
  text,
  style,
  textStyle,
  linkStyle,
  seeMoreLabel = 'See more',
  onExpand,
}) {
  const [width, setWidth] = useState(0);
  const { fontScale } = useWindowDimensions();

  // Reset expansion and measurement when content or layout metrics change.
  const measurementKey = JSON.stringify([
    text,
    width,
    fontScale,
    StyleSheet.flatten(textStyle),
  ]);

  return (
    <View style={style}>
      <View
        style={styles.host}
        onLayout={({ nativeEvent }) => {
          const nextWidth = nativeEvent.layout.width;
          setWidth(previous =>
            previous === nextWidth ? previous : nextWidth
          );
        }}
      >
        {width > 0 && (
          <MeasuredText
            key={measurementKey}
            text={text}
            width={width}
            textStyle={textStyle}
            linkStyle={linkStyle}
            seeMoreLabel={seeMoreLabel}
            onExpand={onExpand}
          />
        )}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
