    alignSelf: 'stretch',
  },
  content: {
    position: 'relative',
  },
  measurement: {
    position: 'absolute',
    top: 0,
    left: 0,
    opacity: 0,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'baseline',
  },
  text: {
    fontSize: 16,
    lineHeight: 24,
    color: '#222',
  },
  preview: {
    flexShrink: 1,
    minWidth: 0,
  },
  button: {
    flexShrink: 0,
    marginStart: 6,
  },
