**Scoring assumptions:** best of three sets; advantage scoring; a seven-point, win-by-two tiebreak at 6–6 in every set. Tap the **point winner** to enter a score. In advanced mode, errors are attributed to the opponent of the point winner.

```swift
import SwiftUI

enum PointKind: String, CaseIterable, Identifiable {
    case winner = "Winner"
    case unforcedError = "Unforced error"
    case forcedError = "Forced error"
    case ace = "Ace"
    case returnWinner = "Return winner"
    case serveWinner = "Serve winner"

    var id: String { rawValue }

    var isError: Bool {
        self == .unforcedError || self == .forcedError
    }
}

struct PointRecord: Identifiable {
    let id = UUID()
    let winner: Int
    let kind: PointKind?
    let set: Int
    let game: Int
    let wasTiebreak: Bool

    // A winner/ace belongs to the point winner;
    // an error belongs to the player who lost the point.
    var actor: Int {
        kind?.isError == true ? 1 - winner : winner
    }
}

struct CompletedSet {
    let games: [Int]
    let tiebreak: [Int]?

    var winner: Int {
        games[0] > games[1] ? 0 : 1
    }
}

struct ScoreState {
    var points = [0, 0]
    var games = [0, 0]
    var completedSets: [CompletedSet] = []

    var isTiebreak: Bool {
        games == [6, 6]
    }

    func setsWon(by player: Int) -> Int {
        completedSets.filter { $0.winner == player }.count
    }

    var matchWinner: Int? {
        if setsWon(by: 0) == 2 { return 0 }
        if setsWon(by: 1) == 2 { return 1 }
        return nil
    }

    func pointLabel(for player: Int) -> String {
        if matchWinner != nil { return "—" }
        if isTiebreak { return "\(points[player])" }

        let opponent = 1 - player
        if points[0] >= 3 && points[1] >= 3 {
            return points[player] > points[opponent] ? "AD" : "40"
        }
        return ["0", "15", "30", "40"][points[player]]
    }

    mutating func awardPoint(to player: Int) {
        guard matchWinner == nil else { return }

        let opponent = 1 - player
        points[player] += 1

        if isTiebreak {
            if points[player] >= 7 &&
                points[player] - points[opponent] >= 2 {
                let finalTiebreak = points
                games[player] += 1
                finishSet(tiebreak: finalTiebreak)
            }
            return
        }

        guard points[player] >= 4,
              points[player] - points[opponent] >= 2 else {
            return
        }

        games[player] += 1
        points = [0, 0]

        if games[player] >= 6 &&
            games[player] - games[opponent] >= 2 {
            finishSet(tiebreak: nil)
        }
    }

    private mutating func finishSet(tiebreak: [Int]?) {
        completedSets.append(
            CompletedSet(games: games, tiebreak: tiebreak)
        )
        games = [0, 0]
        points = [0, 0]
    }
}

