Replace the receive loop with:

```c
while (1) {
    cli_len = sizeof(cli_addr);

    /*
     * On Linux, MSG_TRUNC makes recvfrom return the actual datagram
     * length, so oversized packets cannot be mistaken for valid ones.
     */
    ssize_t n = recvfrom(
        sockfd,
        buffer,
        sizeof(buffer),
        MSG_TRUNC,
        (struct sockaddr *)&cli_addr,
        &cli_len
    );

    if (n < 0) {
        if (errno == EINTR)
            continue;
        perror("recvfrom");
        continue;
    }

    if ((size_t)n != PACKET_SIZE) {
        fprintf(stderr, "Invalid packet size: %zd\n", n);
        continue;
    }

    /* Validate the entire packet before applying any events. */
    int indices[EVENT_COUNT];
    int values[EVENT_COUNT];
    unsigned char seen[EVENT_COUNT] = {0};
    int valid = 1;

    for (size_t i = 0; i < EVENT_COUNT; ++i) {
        indices[i] = read_le_i16(buffer + i * 4);
        values[i] = read_le_i16(buffer + i * 4 + 2);

        if (indices[i] < 0 || (size_t)indices[i] >= EVENT_COUNT) {
            valid = 0;
            break;
        }

        size_t idx = (size_t)indices[i];

        if (seen[idx]) {
            valid = 0;
            break;
        }
        seen[idx] = 1;

        if (REGISTERED_EVENTS[idx].type == EV_KEY &&
            values[i] != 0 && values[i] != 1) {
            valid = 0;
            break;
        }
    }

    if (!valid) {
        fprintf(stderr, "Invalid controller state\n");
        continue;
    }

    for (size_t i = 0; i < EVENT_COUNT; ++i) {
        const struct controller_event *event =
            &REGISTERED_EVENTS[indices[i]];

        int rc = libevdev_uinput_write_event(
            controller, event->type, event->code, values[i]
        );
        if (rc < 0)
            fprintf(stderr, "write_event: %s\n", strerror(-rc));
