```c
static void udp_server(void)
{
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in serv_addr = {0};
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    serv_addr.sin_port = htons(PORT);

    if (bind(sockfd, (struct sockaddr *)&serv_addr,
             sizeof(serv_addr)) < 0) {
        perror("bind");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    /*
     * The extra byte lets us reject oversized datagrams, even when
     * recvfrom truncates them to the buffer size.
     */
    uint8_t buffer[PACKET_SIZE + 1];

    for (;;) {
        ssize_t n = recvfrom(sockfd, buffer, sizeof(buffer),
                             0, NULL, NULL);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            perror("recvfrom");
            continue;
        }

        if (n != (ssize_t)PACKET_SIZE) {
            fprintf(stderr, "Invalid packet length: %zd\n", n);
            continue;
        }

        int indices[EVENT_COUNT];
        int values[EVENT_COUNT];
        unsigned char seen[EVENT_COUNT] = {0};
        int valid = 1;

        /* Validate the entire state before emitting any events. */
        for (size_t i = 0; i < EVENT_COUNT; ++i) {
            int index = read_i16_le(buffer + i * 4);
            int value = read_i16_le(buffer + i * 4 + 2);

            if (index < 0 || (size_t)index >= EVENT_COUNT) {
                valid = 0;
                break;
            }

            if (seen[index] ||
                (REGISTERED_EVENTS[index].type == EV_KEY &&
                 value != 0 && value != 1)) {
                valid = 0;
                break;
            }

            seen[index] = 1;
            indices[i] = index;
            values[i] = value;
        }

        if (!valid) {
            fprintf(stderr, "Invalid controller state\n");
            continue;
        }

        for (size_t i = 0; i < EVENT_COUNT; ++i) {
            const struct controller_event *event =
                &REGISTERED_EVENTS[indices[i]];

            int rc = libevdev_uinput_write_event(
                controller, event->type, event->code, values[i]);

            if (rc < 0)
                fprintf(stderr, "write event: %s\n", strerror(-rc));
        }

        int rc = libevdev_uinput_write_event(
            controller, EV_SYN, SYN_REPORT, 0);

        if (rc < 0)
            fprintf(stderr, "write sync: %s\n", strerror(-rc));
    }
}
```

