public void moveToCenter()
{
    if (Storage == null || speed <= 0f)
    {
        Debug.LogWarning("Assign Storage and use a positive speed.");
        return;
    }

    if (activeMove != null)
        StopCoroutine(activeMove);

    Vector3 target = new Vector3(
        Storage.movePos.x * dir,
        Storage.movePos.y,
        Storage.movePos.z
    );

    Quaternion targetRotation = Quaternion.Euler(Storage.rot);

    activeMove = StartCoroutine(Move(target, targetRotation));
