private IEnumerator Move(Vector3 endPos, Quaternion endRotation)
{
    // These are snapshots, independent of the moving Transform.
    Vector3 startPos = transform.position;
    Quaternion startRotation = transform.rotation;

    float length = Vector3.Distance(startPos, endPos);
    float duration = length / speed;
    float elapsed = 0f;

    while (elapsed < duration)
    {
        float progress = elapsed / duration;

        transform.position = Vector3.Lerp(startPos, endPos, progress);
        transform.rotation =
            Quaternion.Lerp(startRotation, endRotation, progress);

        yield return null;
        elapsed += Time.deltaTime;
    }

    // Also handles a zero-length journey without dividing by zero.
    transform.position = endPos;
    transform.rotation = endRotation;
}
