## My answer to the prompt

Find the connected components formed by the existing roads. In each component, select its cheapest house. Then connect the globally cheapest house to the cheapest house of every other component.

### Why this is optimal

Suppose there are \(k\) components. Because all construction costs are positive, an optimal solution connects them with a tree containing \(k-1\) new roads.

Root any such tree at the component containing the globally cheapest house, whose price is \(g\). For each other component \(C\), its edge to its parent costs at least
\[
\min_{v\in C} a_v + g.
\]
Our construction achieves this lower bound for every component by connecting its cheapest house directly to the globally cheapest house. Therefore, it has minimum total cost.

### C++ solution

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, sz;

    explicit DSU(int n) : parent(n + 1), sz(n + 1, 1) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int v) {
        if (parent[v] == v) return v;
        return parent[v] = find(parent[v]);
    }

    void unite(int u, int v) {
        u = find(u);
        v = find(v);
        if (u == v) return;

        if (sz[u] < sz[v]) swap(u, v);
        parent[v] = u;
        sz[u] += sz[v];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<int> a(n + 1);
    int hub = 1;
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
        if (a[i] < a[hub]) hub = i;
    }

    DSU dsu(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        dsu.unite(u, v);
    }

    vector<int> cheapest(n + 1, -1);
    for (int i = 1; i <= n; ++i) {
        int root = dsu.find(i);
        if (cheapest[root] == -1 || a[i] < a[cheapest[root]]) {
            cheapest[root] = i;
        }
    }

    int hubRoot = dsu.find(hub);
    vector<pair<int, int>> roads;

    for (int root = 1; root <= n; ++root) {
        if (cheapest[root] != -1 && root != hubRoot) {
            roads.emplace_back(hub, cheapest[root]);
        }
    }

    cout << roads.size() << '\n';
    for (auto [u, v] : roads) {
        cout << u << ' ' << v << '\n';
    }
}
```

**Complexity:** \(O((n+m)\alpha(n))\) time and \(O(n)\) auxiliary space. If the graph is already connected, the program prints `0`.

