    }
    if (text.isEmpty())
        return false;

    int base = 10;
    QString digits = text;
    bool integerNotation = false;

    if (text.startsWith("0x", Qt::CaseInsensitive)) {
        base = 16;
        digits = text.mid(2);
        integerNotation = true;
    } else if (text.startsWith("0b", Qt::CaseInsensitive)) {
        base = 2;
        digits = text.mid(2);
        integerNotation = true;
    } else if (text.startsWith("0o", Qt::CaseInsensitive)) {
        base = 8;
        digits = text.mid(2);
        integerNotation = true;
    } else {
        static const QRegularExpression integerSyntax(
            QStringLiteral("\\A[0-9]+\\z"));

        if (integerSyntax.match(text).hasMatch()) {
            integerNotation = true;
            if (text.size() > 1 && text.startsWith('0'))
                base = 8; // Chosen convention: leading-zero octal.
        }
    }

    if (integerNotation) {
        const QString pattern =
            base == 16 ? QStringLiteral("\\A[0-9A-Fa-f]+\\z") :
            base == 8  ? QStringLiteral("\\A[0-7]+\\z") :
            base == 2  ? QStringLiteral("\\A[01]+\\z") :
                         QStringLiteral("\\A[0-9]+\\z");

        if (!QRegularExpression(pattern).match(digits).hasMatch())
            return false;

        bool ok = false;
        const qlonglong n = (sign + digits).toLongLong(&ok, base);

        // Compare integers directly; no rounding or narrowing conversion.
        return ok &&
               (n == 0 || n == 1 || n == 2 || n == 3 ||
                n == 10 || n == 11 || n == 42);
    }

    // Decimal fractions and scientific notation.
    static const QRegularExpression decimalSyntax(QStringLiteral(
        "\\A(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)"
        "(?:[eE][+-]?[0-9]+)?\\z"));

    if (!decimalSyntax.match(text).hasMatch())
        return false;

    bool ok = false;
    const double n = (sign + text).toDouble(&ok);
    return ok && allowed(n);
}

static bool allowedCellValue(const QVariant &value)
{
    if (!value.isValid() || value.isNull())
        return false;

    // Inspect the actual type, not merely whether conversion is possible.
    switch (value.userType()) {
    case QMetaType::QString:
        return allowedText(value.toString());

    case QMetaType::Int:
    case QMetaType::UInt:
    case QMetaType::LongLong:
    case QMetaType::ULongLong:
    case QMetaType::Float:
    case QMetaType::Double: {
        bool ok = false;
        const double n = value.toDouble(&ok);
        return ok && allowed(n);
    }

    default:
        // Reject booleans, dates, and other nonnumeric cell values.
        return false;
    }
}

int main(int argc, char *argv[])
{
    QCoreApplication app(argc, argv);

    if (argc != 3) {
        qCritical() << "Usage: validator file.xlsx A1";
        return 2;
    }

    QXlsx::Document document(QString::fromLocal8Bit(argv[1]));
    if (!document.load()) {
        qCritical() << "Cannot load workbook";
        return 2;
    }

    // Reads from the workbook's current worksheet.
    const QString address = QString::fromLocal8Bit(argv[2]);
    const bool valid = allowedCellValue(document.read(address));

    qInfo() << address << (valid ? "VALID" : "INVALID");
    return valid ? 0 : 1;
}
```

