Use a discriminated union so TypeScript can distinguish success from failure. Keep caught errors as `unknown`: JavaScript can throw any value, not just an `Error`.

```ts
export type Result<T, E = unknown> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly error: E };

/** Executes a synchronous callback and captures thrown values. */
export function tryCatch<T>(fn: () => T): Result<T> {
  try {
    return { ok: true, value: fn() };
  } catch (error: unknown) {
    return { ok: false, error };
  }
}

/** Captures both synchronous throws and asynchronous rejections. */
export async function tryCatchAsync<T>(
  fn: () => T | PromiseLike<T>,
): Promise<Result<T>> {
  try {
    return { ok: true, value: await fn() };
  } catch (error: unknown) {
    return { ok: false, error };
  }
}
```

Usage:

```ts
const result = tryCatch(() => {
  const value = Number("42");
  if (!Number.isFinite(value)) {
    throw new Error("Invalid number");
  }
  return value;
});

