  console.log(result.value); // number
} else {
  console.error(
    result.error instanceof Error
      ? result.error.message
      : String(result.error),
  );
}
```

Pass a callback, not an already-executed function call. Use `tryCatchAsync` for promise-returning callbacks; the synchronous version cannot capture later promise rejections.

