Do you mean the sum **closest to `b` even if it exceeds it**, or the **largest sum that does not exceed `b`**? Assuming you mean the closest sum on either side, choosing one integer from each array:

```javascript
function getExpense(arr1, arr2, b) {
  let best = null;

  for (const x of arr1) {
    for (const y of arr2) {
      const sum = x + y;

      if (
        best === null ||
        Math.abs(sum - b) < Math.abs(best - b) ||
        (Math.abs(sum - b) === Math.abs(best - b) && sum < best)
      ) {
        best = sum;
      }

      if (sum === b) return sum;
    }
  }

  return best;
}

console.log(getExpense([1, 5, 10], [2, 6], 7)); // 7
console.log(getExpense([1, 2], [3, 4], 100));    // 6
```

This returns `null` if either array is empty, supports negative integers, and prefers the smaller sum when two sums are equally close. Time complexity is **O(n × m)**, with **O(1)** extra space.

