  { name: "findPosition", label: "Find Position", body: {} },
  { name: "detectObjects", label: "Detect Objects", body: {} },
  { name: "classifyImage", label: "Classify Image", body: {} },
];

const PostApiPanel = ({ apiPrefix }) => {
  const [method, setMethod] = useState(postMethods[0].name);
  const [requestBody, setRequestBody] = useState("{}");
  const [responseBody, setResponseBody] = useState("");
  const [lastRequest, setLastRequest] = useState(null);
  const [status, setMessage] = useState("");
  const [busy, setBusy] = useState(false);

  const requestUrl = `/api/${apiPrefix}/${method}`;

  const selectMethod = (item) => {
    setMethod(item.name);
    setRequestBody(JSON.stringify(item.body, null, 2));
    setResponseBody("");
    setLastRequest(null);
    setMessage("");
  };

  const send = async (saveMock = false) => {
    setBusy(true);
    setMessage("");

    try {
      // Validate JSON before making either request.
      const payload = saveMock
        ? { api: method, response: JSON.parse(responseBody) }
        : JSON.parse(requestBody);

      const url = saveMock
        ? `/api/${apiPrefix}/setResponse`
        : requestUrl;

      const body = JSON.stringify(payload, null, 2);
