// users.ts
import type { APIRequestContext } from '@playwright/test';

export interface CreateUserPayload {
  username: string;
  email: string;
  password: string;
}

export interface Credentials {
  username: string;
  password: string;
}

export interface ProvisionedUser extends Credentials {
  id: string;
}

export interface UsersApi {
  create(payload: CreateUserPayload): Promise<{ id: string }>;
  setRole(id: string, role: string): Promise<Credentials>;
  delete(id: string): Promise<void>;
}

// HTTP concerns only; no UI or provisioning workflow.
export class PlaywrightUsersApi implements UsersApi {
  constructor(private readonly request: APIRequestContext) {}

  async create(payload: CreateUserPayload): Promise<{ id: string }> {
    const response = await this.request.post('/users/v2/create', {
      data: payload,
    });

    if (response.status() !== 201) {
      throw new Error(`Create user failed: HTTP ${response.status()}`);
    }

    const body = await response.json();

    if (typeof body.id !== 'string' || !body.id) {
      throw new Error('Create user response is missing a valid id');
    }

    return { id: body.id };
  }

  async setRole(id: string, role: string): Promise<Credentials> {
    const response = await this.request.post('/users/v2/permissions', {
      data: { id, role },
    });

    if (response.status() !== 200) {
      throw new Error(`Set permissions failed: HTTP ${response.status()}`);
    }

    const body = await response.json();

    if (
      typeof body.username !== 'string' ||
      typeof body.password !== 'string' ||
      !body.username ||
      !body.password
    ) {
      throw new Error('Permissions response is missing credentials');
    }

    return { username: body.username, password: body.password };
  }

  async delete(id: string): Promise<void> {
    const response = await this.request.delete(
      `/users/v2/${encodeURIComponent(id)}`,
    );

    // Treat an already-deleted user as successfully cleaned up.
    if (!response.ok() && response.status() !== 404) {
      throw new Error(`Delete user failed: HTTP ${response.status()}`);
    }
  }
}

// Workflow and test-resource lifecycle concerns only.
export class UserProvisioner {
  private readonly createdIds: string[] = [];

  constructor(private readonly users: UsersApi) {}

  async createWithRole(
    payload: CreateUserPayload,
    role: string,
  ): Promise<ProvisionedUser> {
    const { id } = await this.users.create(payload);

    // Track immediately so cleanup also covers permission-update failures.
    this.createdIds.push(id);

    const credentials = await this.users.setRole(id, role);
    return { ...credentials, id };
  }

  async cleanup(): Promise<void> {
    // Attempt every deletion, even if one fails.
    const failures: unknown[] = [];

    for (const id of this.createdIds.splice(0).reverse()) {
      try {
        await this.users.delete(id);
      } catch (error) {
        failures.push(error);
      }
    }

    if (failures.length > 0) {
      throw new Error(`Cleanup failed for ${failures.length} user(s)`);
    }
  }
}
```

