要求中“使用 `strlen`”与“不能用系统函数”存在冲突。下面按 **允许使用题目明确指定的 `strlen`，不使用其他辅助函数或自定义函数** 来实现。

```cpp
#include <iostream>
#include <cstring>
using namespace std;

int main() {
    char a[105];
    int num[105] = {0};
    int b;

    cin >> a;
    cin >> b;

    int n = strlen(a);

    // 转换为 int 数组，num[0] 留给最高位进位
    for (int i = 0; i < n; i++) {
        num[i + 1] = a[i] - '0';
    }

    int carry = b;

    // 从个位开始相加
    for (int i = n; i >= 1; i--) {
        num[i] += carry;

        if (num[i] >= 10) {
            num[i] -= 10;
            carry = 1;
        } else {
            carry = 0;
        }
    }

    num[0] = carry;

    if (num[0] != 0) {
        cout << num[0];
    }

    for (int i = 1; i <= n; i++) {
        cout << num[i];
    }
    cout << '\n';

    return 0;
}
```

每位相加的结果最多为 18，因此出现进位时减去一次 10 即可。时间复杂度为 \(O(n)\)。

