#ifndef CHART_WIDGET_H
#define CHART_WIDGET_H

#include <FL/Fl_Widget.H>
#include <cstddef>
#include <iosfwd>
#include <map>
#include <string>
#include <vector>

class ChartWidget : public Fl_Widget {
public:
    struct Point {
        float x;
        float y;
    };

    using GraphId = std::size_t;

    enum class PlotStyle {
        Lines,
        Points,
        LinesAndPoints
    };

    struct GraphStyle {
        Fl_Color color = FL_BLUE;
        int lineWidth = 1;     // Pixels; must be positive
        PlotStyle plot = PlotStyle::Lines;
    };

    struct AxisSettings {
        std::string name;
        float minimum = 0.0f;
        float maximum = 1.0f;
    };

    struct GridSettings {
        bool verticalVisible = true;
        bool horizontalVisible = true;
        float xStep = 0.1f;    // In data coordinates; must be positive
        float yStep = 0.1f;
        Fl_Color color = FL_LIGHT2;
        int lineWidth = 1;
    };

    ChartWidget(int x, int y, int width, int height,
                const char* label = nullptr);
    ~ChartWidget() override = default;

    // Graph IDs remain valid until their graph is removed.
    GraphId addGraph(const std::string& name);
    bool removeGraph(GraphId id);
    bool renameGraph(GraphId id, const std::string& name);
    bool setGraphStyle(GraphId id, const GraphStyle& style);

    // Point indices refer to the current position within a graph.
    bool addPoint(GraphId id, Point point);
    bool removePoint(GraphId id, std::size_t pointIndex);
    bool setPoints(GraphId id, const std::vector<Point>& points);
    bool clearPoints(GraphId id);

    // Set both names and displayed ranges.
    // Return false for nonfinite bounds or minimum >= maximum.
    bool setXAxis(const AxisSettings& settings);
    bool setYAxis(const AxisSettings& settings);

    // Return false for invalid steps or line widths.
    bool setGrid(const GridSettings& settings);

    std::size_t graphCount() const noexcept;
    void printInfo(std::ostream& output) const;

    // Resizes the widget's pixel rectangle.
    void resize(int x, int y, int width, int height) override;

protected:
    void draw() override;

private:
    struct Graph {
        std::string name;
        std::vector<Point> points;
        GraphStyle style;
    };

    struct PlotRect {
        int x, y, width, height;
    };

    std::map<GraphId, Graph> graphs_;
    GraphId nextId_ = 1;

    AxisSettings xAxis_{"X", 0.0f, 1.0f};
    AxisSettings yAxis_{"Y", 0.0f, 1.0f};
    GridSettings grid_;

    PlotRect plotRect() const;
    double screenX(float x, const PlotRect& area) const;
    double screenY(float y, const PlotRect& area) const;

    void drawGrid(const PlotRect& area);
    void drawGraphs(const PlotRect& area);
    void drawAxesAndLabels(const PlotRect& area);
};

#endif
```

**One C++11 compatibility adjustment:** because `AxisSettings` has default member initializers, add this constructor to it if using C++11 rather than C++14 or later:

```cpp
AxisSettings(const std::string& label = "",
             float low = 0.0f, float high = 1.0f)
    : name(label), minimum(low), maximum(high) {}
```

Implementation considerations:

- Use `<FL/fl_draw.H>` in the `.cpp` file for drawing.
- Call `redraw()` after successful data or appearance changes.
- Reserve margins for axis names and tick labels.
- Map X normally and invert Y, since screen Y increases downward.
- Clip plotted lines and markers to the plot rectangle.
- Reject nonfinite point coordinates and protect grid generation against excessively small steps.
- Draw connected points in insertion order; callers should supply increasing X values when that is appropriate for their function.
- `std::vector<Point>` is an efficient list-like container for plotting many points. A linked list is unnecessary unless its particular insertion/removal behavior is required.

