### 4. Implement the guide controller in JavaScript

```html
<script>
const dialog = document.querySelector("#guide");
const form = document.querySelector("#registration");
const steps = [...form.querySelectorAll(".step")];
const back = document.querySelector("#back");
const next = document.querySelector("#next");
const finish = document.querySelector("#finish");
const error = document.querySelector("#error");
let index = 0;
let busy = false;

function currentInput() {
    return steps[index].querySelector("input");
}

function showStep(target) {
    index = target;

    steps.forEach((step, i) => {
        step.disabled = i !== index;
        step.inert = i !== index;
        step.classList.toggle("active", i === index);
    });

    back.disabled = index === 0;
    next.hidden = index === steps.length - 1;
    finish.hidden = index !== steps.length - 1;

    document.querySelector("#progress").textContent =
        `Step ${index + 1} of ${steps.length}`;

    currentInput().focus();
}

document.querySelector("#start").onclick = () => {
    dialog.showModal();
    showStep(index);
};

document.querySelector("#cancel").onclick = () => {
    if (!busy) dialog.close();
};

dialog.addEventListener("cancel", event => {
    if (busy) event.preventDefault();
});

back.onclick = () => {
    error.textContent = "";
    showStep(index - 1);
};

next.onclick = () => {
    if (currentInput().reportValidity()) {
        error.textContent = "";
        showStep(index + 1);
    }
};

form.addEventListener("submit", async event => {
    event.preventDefault();
    if (busy) return;

    // Enter on an earlier field advances instead of submitting early.
    if (index < steps.length - 1) {
        next.click();
        return;
    }

    if (!currentInput().reportValidity()) return;

    // Disabled controls are omitted from FormData.
    // Briefly enable every field, validate, and capture its value.
    steps.forEach(step => step.disabled = false);

    const invalid = steps.findIndex(step =>
        !step.querySelector("input").checkValidity());

    if (invalid !== -1) {
        showStep(invalid);
        currentInput().reportValidity();
        return;
    }

    const payload = new FormData(form);
    showStep(index);

    busy = true;
    error.textContent = "";
    form.inert = true;

    try {
        const response = await fetch(form.action, {
            method: "POST",
            body: payload
        });

        const data = await response.json();

        if (!response.ok) {
            // Expected server contract:
            // { message: "...", field: "Email" }
            form.inert = false;

            const failedStep = steps.findIndex(step =>
                step.querySelector("input").name === data.field);

            if (failedStep >= 0) showStep(failedStep);
            error.textContent = data.message || "Please check your details.";
            return;
        }

        form.reset();
        index = 0;
        dialog.close();
        document.querySelector("#result").textContent =
            "Account created. Check your email for confirmation.";
    } catch {
        error.textContent = "Registration failed. Please try again.";
    } finally {
        busy = false;
        form.inert = false;
        if (dialog.open) currentInput().focus();
    }
});
</script>
```

### 5. Handle registration in ASP.NET Core

Implement the POST action with this contract:

```csharp
[HttpPost]
[ValidateAntiForgeryToken]
public async Task<IActionResult> Register(RegistrationInput input)
{
    if (!ModelState.IsValid)
    {
        var failure = ModelState.First(x => x.Value!.Errors.Count > 0);

        return BadRequest(new
        {
            field = failure.Key,
            message = failure.Value!.Errors[0].ErrorMessage
        });
    }

    var user = new ApplicationUser
    {
        UserName = input.Email,
        Email = input.Email,
        FullName = input.FullName
    };

    var result = await _userManager.CreateAsync(user, input.Password);

    if (!result.Succeeded)
    {
        return BadRequest(new
        {
            message = string.Join(" ", result.Errors.Select(e => e.Description))
        });
    }

    // Send an email confirmation link here.
    return Ok(new { success = true });
}
```

This assumes you have configured ASP.NET Core Identity, injected `UserManager<ApplicationUser>`, and added `FullName` to your `ApplicationUser`.

**Important:** Never store plaintext passwords or registration passwords in browser storage. The guide is a UX feature, not a security boundary: always validate on the server, even if users appear to have completed every step.

For a reusable framework, extract the step controller into a JavaScript module and define each process using field selectors, help text, validation, and transition rules.

