### 3. Reusable step controller

The `steps` array is the process definition. Each step identifies a field and explains how to complete it.

```html
<script>
const form = document.querySelector("#registration");
const help = document.querySelector("#guideHelp");
const result = document.querySelector("#result");
const back = document.querySelector("#back");
const next = document.querySelector("#next");
const cancel = document.querySelector("#cancel");

const steps = [
    { id: "FullName", help: "Enter your full name, then select Next." },
    { id: "Email", help: "Enter a valid email address, then select Next." },
    { id: "Password", help: "Use at least 12 characters, then select Register." }
];

const fields = steps.map(s => document.getElementById(s.id));
const background = [
    ...document.querySelectorAll("[data-guide-background]")
];

let current = 0;
let busy = false;

function showStep(index) {
    current = index;

    fields.forEach((field, i) => {
        field.disabled = i !== index;

        const container = field.closest(".field");
        container.inert = i !== index;
        container.classList.toggle("active", i === index);
    });

    background.forEach(element => element.inert = true);

    help.textContent =
        `Step ${index + 1} of ${steps.length}: ${steps[index].help}`;

    back.disabled = index === 0;
    next.textContent =
        index === steps.length - 1 ? "Register" : "Next";

    fields[index].focus();
}

function validateCurrent() {
    const field = fields[current];

    field.setCustomValidity(
        field.value.trim() ? "" : "Please complete this field."
    );

    return field.reportValidity();
}

fields.forEach(field => {
    field.addEventListener("input", () => field.setCustomValidity(""));
});

back.addEventListener("click", () => {
    if (!busy && current > 0) showStep(current - 1);
});

next.addEventListener("click", async () => {
    if (busy || !validateCurrent()) return;

    result.textContent = "";

    if (current < steps.length - 1) {
        showStep(current + 1);
        return;
    }

    // Disabled inputs are excluded from ordinary form submission.
    // Reading their values explicitly avoids losing completed steps.
    const payload = Object.fromEntries(
        fields.map(field => [field.id, field.value])
    );

    busy = true;
    next.disabled = back.disabled = cancel.disabled = true;
    fields[current].disabled = true;

    try {
        const response = await fetch(
            '@Url.Action("Submit", "Registration")',
            {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "X-CSRF-TOKEN": form.querySelector(
                        '[name="__RequestVerificationToken"]'
                    ).value
                },
                body: JSON.stringify(payload)
            }
        );

        const body = await response.json();

        if (!response.ok) {
            const messages = Array.isArray(body.errors)
                ? body.errors
                : Object.values(body.errors || {}).flat();

            throw new Error(
                messages.join(" ") || "Registration failed."
            );
        }

        result.textContent = body.message;
        fields.forEach(field => field.disabled = true);
        fields[2].value = "";
        background.forEach(element => element.inert = false);

        // Keep submission locked after success.
        return;
    } catch (error) {
        result.textContent = error.message;
        busy = false;
        next.disabled = cancel.disabled = false;
        showStep(current);
    }
});

form.addEventListener("submit", event => {
    event.preventDefault();
    if (!busy) next.click();
});

cancel.addEventListener("click", () => {
    if (busy) return;

    background.forEach(element => element.inert = false);
    form.hidden = true;
    fields[2].value = "";
    // In production, restore focus to the control that launched the guide.
});

showStep(0);
</script>
```

This keeps completed values while disabling their fields, supports going back, submits without navigating away, and leaves a deliberate Cancel escape route. `inert` prevents keyboard and pointer interaction with inactive containers; a visual overlay alone would not.

For a larger framework, extract the JavaScript into a class accepting step definitions, validation callbacks, and completion handlers. Map server validation errors back to the corresponding step so users can immediately correct the relevant field. Treat browser-side locking as UX—not authorization or security.

