## My answer to the user prompt

Use a height-constrained scrolling container, sticky table headers, and a Pinia action that fetches the next batch. After each fetch, check the container again: if the rows still do not fill the available space, fetch another batch.

This example assumes:

- `start` is a zero-based row offset.
- The API returns `{ rows: [...] }`, optionally with `total`.
- Without `total`, a batch shorter than `count` means there are no more rows.

### Pinia store

```javascript
// src/stores/rows.js
import { defineStore } from 'pinia';

export const useRowsStore = defineStore('rows', {
  state: () => ({
    rows: [],
    loading: false,
    hasMore: true,
    error: null,
  }),

  actions: {
    async fetchNext(count = 40) {
      if (this.loading || !this.hasMore) return false;

      this.loading = true;
      this.error = null;

      try {
        const start = this.rows.length;
        const response = await fetch(
          `/api/rows?start=${start}&count=${count}`
        );

        if (!response.ok) {
          throw new Error(`Request failed: ${response.status}`);
        }

        const data = await response.json();
        if (!Array.isArray(data.rows)) {
          throw new Error('Expected a rows array');
        }

        this.rows.push(...data.rows);

        this.hasMore =
          data.rows.length > 0 &&
          (typeof data.total === 'number'
            ? this.rows.length < data.total
            : data.rows.length === count);

        return true;
      } catch (error) {
        this.error = error.message;
        return false;
      } finally {
        this.loading = false;
      }
    },
  },
});
```

### Table component

```vue
<!-- src/components/InfiniteScrollingTable.vue -->
<script setup>
import { ref, nextTick, onMounted, onBeforeUnmount } from 'vue';
import { useRowsStore } from '../stores/rows';

const store = useRowsStore();
const viewport = ref(null);

const threshold = 120;
let checking = false;
let disposed = false;
let resizeObserver;

function nearBottom() {
  const el = viewport.value;
  return el &&
    el.scrollHeight - el.scrollTop - el.clientHeight <= threshold;
}

async function fillAvailableSpace() {
  if (checking || disposed) return;
  checking = true;

  try {
    await nextTick();

    // Continue fetching when the initial batch does not fill the viewport,
    // or when the user remains near the bottom after a fetch.
    while (
      !disposed &&
      nearBottom() &&
      store.hasMore &&
      !store.loading &&
      !store.error
    ) {
      const succeeded = await store.fetchNext();
      if (!succeeded) break;
      await nextTick();
    }
  } finally {
    checking = false;
  }
}

function retry() {
  store.error = null;
  void fillAvailableSpace();
}

onMounted(() => {
  resizeObserver = new ResizeObserver(() => {
    void fillAvailableSpace();
  });
  resizeObserver.observe(viewport.value);

  void fillAvailableSpace();
});

onBeforeUnmount(() => {
  disposed = true;
  resizeObserver?.disconnect();
});
</script>

<template>
  <div
    ref="viewport"
    class="table-viewport"
