        {{ store.error }}
        <button @click="retry">Retry</button>
      </template>

      <span v-else-if="!store.hasMore">
        {{ store.rows.length ? 'All rows loaded.' : 'No rows found.' }}
      </span>
    </div>
  </div>
</template>

<script setup>
import { ref, nextTick, onMounted, onBeforeUnmount } from 'vue';
import { useRowsStore } from '../stores/rows';

const store = useRowsStore();
const container = ref(null);

const threshold = 150;
let filling = false;
let disposed = false;
let resizeObserver;

function nearBottom() {
  const el = container.value;

  return el && el.clientHeight > 0 &&
    el.scrollHeight - el.scrollTop - el.clientHeight <= threshold;
}

async function fill() {
  if (filling || disposed || store.error) return;

  filling = true;

  try {
    await nextTick();

    // Keep fetching until the available space is filled, plus a small
    // buffer, or until the API has no more data.
    while (
      !disposed &&
      store.hasMore &&
      !store.error &&
      nearBottom()
    ) {
      const loaded = await store.loadNext();

      if (!loaded) break;

      // Measure again only after Vue renders the new rows.
      await nextTick();
    }
  } finally {
    filling = false;
  }
}

function retry() {
  store.error = null;
  void fill();
}

onMounted(() => {
  resizeObserver = new ResizeObserver(() => {
    void fill();
  });

  resizeObserver.observe(container.value);
  void fill();
});

onBeforeUnmount(() => {
  disposed = true;
  resizeObserver?.disconnect();
});
</script>

