### Câu trả lời của tôi cho yêu cầu

Dưới đây là chương trình C cài đặt thuật toán Euclide mở rộng theo đúng các bước bạn đưa ra. Chương trình nhận hai số nguyên không âm \(a, b\), không đồng thời bằng 0, và tìm \(d, x, y\) sao cho:

\[
d = \gcd(a,b), \qquad ax + by = d.
\]

```c
#include <stdio.h>

long long euclidMoRong(long long a, long long b,
                      long long *x, long long *y) {
    if (b == 0) {
        *x = 1;
        *y = 0;
        return a;
    }

    long long x2 = 1, x1 = 0;
    long long y2 = 0, y1 = 1;

    while (b > 0) {
        long long q = a / b;
        long long r = a - q * b;
        long long xMoi = x2 - q * x1;
        long long yMoi = y2 - q * y1;

        a = b;
        b = r;
        x2 = x1;
        x1 = xMoi;
        y2 = y1;
        y1 = yMoi;
    }

    *x = x2;
    *y = y2;
    return a;
}

int main(void) {
    long long a, b, x, y;

    printf("Nhap hai so nguyen khong am a, b: ");
    if (scanf("%lld %lld", &a, &b) != 2 ||
        a < 0 || b < 0 || (a == 0 && b == 0)) {
        printf("Du lieu khong hop le.\n");
        return 1;
    }

    long long d = euclidMoRong(a, b, &x, &y);

    printf("d = %lld, x = %lld, y = %lld\n", d, x, y);
    printf("%lld * (%lld) + %lld * (%lld) = %lld\n",
           a, x, b, y, d);

    return 0;
}
```

Ví dụ, nhập `35 15` sẽ nhận được `d = 5, x = 1, y = -2`, vì \(35 \times 1 + 15 \times (-2) = 5\).

