```java
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Stairs {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            System.out.print("请输入台阶数 n：");

            if (!scanner.hasNextInt()) {
                System.out.println("请输入非负整数。");
                return;
            }

            int n = scanner.nextInt();
            if (n < 0) {
                System.out.println("台阶数不能为负数。");
                return;
            }

            System.out.println("总方法数：" + countWays(n));
            System.out.println("所有走法（每个数字表示这一步跨几级）：");
            printWays(n, new ArrayList<>());
        }
    }

    // f(0) = 1，f(1) = 1，f(n) = f(n - 1) + f(n - 2)
    private static BigInteger countWays(int n) {
        BigInteger previous = BigInteger.ONE;
        BigInteger current = BigInteger.ONE;

        for (int i = 1; i < n; i++) {
            BigInteger next = previous.add(current);
            previous = current;
            current = next;
        }

        return current;
    }

    private static void printWays(int remaining, List<Integer> path) {
        if (remaining == 0) {
            System.out.println(path);
            return;
        }

        for (int step = 1; step <= 2; step++) {
            if (step <= remaining) {
                path.add(step);
                printWays(remaining - step, path);
                path.remove(path.size() - 1); // 回溯
            }
        }
    }
}
```

输入 `3` 时，结果为：

```text
