    // 只要还有一个数未处理完，就继续检查
    while (a || b || c) {
        if ((a % k + b % k) % k != c % k)
            return false;
        a /= k;
        b /= k;
        c /= k;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        ll a, b, c;
        cin >> a >> b >> c;

        ll d = a + b - c;
        if (d < 0) {
            cout << 0 << '\n';
            continue;
        }
        if (d == 0) {
            cout << -1 << '\n';
            continue;
        }

        int ans = 0;
        for (ll i = 1; i * i <= d; ++i) {
            if (d % i != 0) continue;

            if (i >= 2 && check(a, b, c, i))
                ++ans;

            ll j = d / i;
            if (j != i && j >= 2 && check(a, b, c, j))
                ++ans;
        }

        cout << ans << '\n';
    }

    return 0;
}
```

### 复杂度

设 \(V=\max(a,b,c)\)，\(\tau(d)\) 为 \(d\) 的因数个数。对于 \(d>0\)：

- 时间复杂度：\(O(\sqrt d+\tau(d)\log(V+1))\)。
- 额外空间复杂度：\(O(1)\)。

